package org.ofdrw.converter.font;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

public class TrueTypeFontParseTests {

    @Test
    void parseRejectsFontWithoutHeadTableWithIllegalArgumentException() {
        TrueTypeFont font = new TrueTypeFont();

        byte[] data = sfntWithSingleUnrelatedTable();

        assertThrows(IllegalArgumentException.class,
                () -> font.parse(new MemoryTTFDataStream(data)));
    }

    @Test
    void parseReadsRequiredTablesAndReturnsTheSameFontInstance() throws IOException {
        TrueTypeFont font = new TrueTypeFont();

        TrueTypeFont parsed = font.parse(new MemoryTTFDataStream(minimalTrueTypeFont()));

        assertSame(font, parsed);
        assertNull(parsed.getGlyph(0));
        assertNull(parsed.getGlyph(-1));
    }

    @Test
    void parseReportsMissingMaxpAfterReadingHead() {
        TrueTypeFont font = new TrueTypeFont();
        font.fontFamily = "unchanged-family";
        font.fontSubFamily = "unchanged-style";
        font.psName = "unchanged-postscript-name";

        assertThrows(IllegalArgumentException.class,
                () -> font.parse(new MemoryTTFDataStream(fontWithHeadOnly())));

        assertEquals("unchanged-family", font.fontFamily);
        assertEquals("unchanged-style", font.fontSubFamily);
        assertEquals("unchanged-postscript-name", font.psName);
    }

    private static byte[] sfntWithSingleUnrelatedTable() {
        ByteBuffer buffer = ByteBuffer.allocate(28).order(ByteOrder.BIG_ENDIAN);
        buffer.putInt(0x00010000);
        buffer.putShort((short) 1);
        buffer.putShort((short) 0);
        buffer.putShort((short) 0);
        buffer.putShort((short) 0);
        buffer.put(new byte[] {'x', 'x', 'x', 'x'});
        buffer.putInt(0);
        buffer.putInt(0);
        buffer.putInt(0);
        return buffer.array();
    }

    private static byte[] fontWithHeadOnly() {
        int headOffset = 28;
        ByteBuffer buffer = ByteBuffer.allocate(headOffset + 54).order(ByteOrder.BIG_ENDIAN);
        buffer.putInt(0x00010000);
        buffer.putShort((short) 1);
        buffer.putShort((short) 0);
        buffer.putShort((short) 0);
        buffer.putShort((short) 0);
        putTableDirectoryEntry(buffer, "head", headOffset, 54);

        buffer.position(headOffset + 18);
        buffer.putShort((short) 1000);
        buffer.position(headOffset + 50);
        buffer.putShort((short) 0);
        return buffer.array();
    }

    private static byte[] minimalTrueTypeFont() {
        int headOffset = 76;
        int maxpOffset = headOffset + 54;
        int locaOffset = maxpOffset + 6;
        int glyfOffset = locaOffset + 2;

        ByteBuffer buffer = ByteBuffer.allocate(glyfOffset).order(ByteOrder.BIG_ENDIAN);
        buffer.putInt(0x00010000);
        buffer.putShort((short) 4);
        buffer.putShort((short) 0);
        buffer.putShort((short) 0);
        buffer.putShort((short) 0);
        putTableDirectoryEntry(buffer, "head", headOffset, 54);
        putTableDirectoryEntry(buffer, "maxp", maxpOffset, 6);
        putTableDirectoryEntry(buffer, "loca", locaOffset, 2);
        putTableDirectoryEntry(buffer, "glyf", glyfOffset, 0);

        buffer.position(headOffset + 18);
        buffer.putShort((short) 1000);
        buffer.position(headOffset + 50);
        buffer.putShort((short) 0);

        buffer.position(maxpOffset + 4);
        buffer.putShort((short) 0);

        buffer.position(locaOffset);
        buffer.putShort((short) 0);

        return buffer.array();
    }

    private static void putTableDirectoryEntry(
            ByteBuffer buffer, String tag, int offset, int length) {
        buffer.put(tag.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1));
        buffer.putInt(0);
        buffer.putInt(offset);
        buffer.putInt(length);
    }

    private static final class MemoryTTFDataStream extends TTFDataStream {
        private final byte[] data;
        private int position;

        private MemoryTTFDataStream(byte[] data) {
            this.data = data.clone();
        }

        @Override
        public int read() {
            return position < data.length ? data[position++] & 0xff : -1;
        }

        @Override
        public long readLong() throws IOException {
            long value = 0;
            for (int i = 0; i < 8; i++) {
                int valuePart = read();
                if (valuePart < 0) {
                    throw new IOException("Unexpected end of data");
                }
                value = (value << 8) | valuePart;
            }
            return value;
        }

        @Override
        public int readUnsignedShort() throws IOException {
            int high = read();
            int low = read();
            if (high < 0 || low < 0) {
                throw new IOException("Unexpected end of data");
            }
            return (high << 8) | low;
        }

        @Override
        public short readSignedShort() throws IOException {
            return (short) readUnsignedShort();
        }

        @Override
        public void seek(long position) throws IOException {
            if (position < 0 || position > data.length) {
                throw new IOException("Invalid position: " + position);
            }
            this.position = (int) position;
        }

        @Override
        public long getCurrentPosition() {
            return position;
        }

        @Override
        public InputStream getOriginalData() {
            return new ByteArrayInputStream(data);
        }

        @Override
        public long getOriginalDataSize() {
            return data.length;
        }

        @Override
        public int read(byte[] target, int offset, int length) {
            if (position >= data.length) {
                return -1;
            }
            int count = Math.min(length, data.length - position);
            System.arraycopy(data, position, target, offset, count);
            position += count;
            return count;
        }

        @Override
        public byte[] read(int length) throws IOException {
            if (length < 0 || position + length > data.length) {
                throw new IOException("Unexpected end of data");
            }
            byte[] result = new byte[length];
            System.arraycopy(data, position, result, 0, length);
            position += length;
            return result;
        }

        @Override
        public void close() {
        }
    }
}

package org.ofdrw.converter.font;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.lang.reflect.Field;

import org.junit.jupiter.api.Test;

class TrueTypeFontParseTests {

    @Test
    void parsesMinimalTrueTypeFontAndAssociatesGlyphDataWithGlyfTable() throws IOException {
        byte[] fontData = minimalTrueTypeFont();

        TrueTypeFont font = new TrueTypeFont();
        TrueTypeFont parsed = font.parse(fontData);

        assertNotSame(font, parsed);
        assertEquals(1000f, privateField(parsed, "unitsPerEm", Float.class));
        assertEquals(1, privateField(parsed, "numGlyphs", Integer.class));
        assertArrayEquals(
                new long[] {0L, 0L},
                privateField(parsed, "glyphOffsets", long[].class));

        int locaOffset = 12 + 4 * 16 + 52 + 6;
        assertArrayEquals(
                new long[] {locaOffset, 4L},
                privateField(parsed, "glyOffset", long[].class));

        assertNull(parsed.fontFamily);
        assertNull(parsed.fontSubFamily);
        assertNull(parsed.psName);
        assertNull(privateField(parsed, "cmaps", Object.class));
        assertNull(privateField(parsed, "hmt", Object.class));
    }

    @Test
    void missingMaxpTableIsReportedAsAnIllegalArgumentException() throws IOException {
        byte[] fontData = fontWithHeadOnly();

        TrueTypeFont font = new TrueTypeFont();
        font.fontFamily = "original-family";
        font.fontSubFamily = "original-subfamily";
        font.psName = "original-postscript-name";

        assertThrows(IllegalArgumentException.class, () -> font.parse(fontData));

        assertEquals("original-family", font.fontFamily);
        assertEquals("original-subfamily", font.fontSubFamily);
        assertEquals("original-postscript-name", font.psName);
    }

    private static <T> T privateField(TrueTypeFont font, String name, Class<T> type) {
        try {
            Field field = TrueTypeFont.class.getDeclaredField(name);
            field.setAccessible(true);
            return type.cast(field.get(font));
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("Unable to access field: " + name, e);
        }
    }

    private static byte[] minimalTrueTypeFont() throws IOException {
        int directoryEnd = 12 + 4 * 16;
        int headOffset = directoryEnd;
        int maxpOffset = headOffset + 52;
        int locaOffset = maxpOffset + 6;
        int glyfOffset = locaOffset + 4;

        ByteArrayOutputStream output = new ByteArrayOutputStream();
        DataOutputStream out = new DataOutputStream(output);

        out.writeInt(0x00010000);
        out.writeShort(4);
        out.writeShort(0);
        out.writeShort(0);
        out.writeShort(0);

        writeTableRecord(out, "head", headOffset, 52);
        writeTableRecord(out, "maxp", maxpOffset, 6);
        writeTableRecord(out, "loca", locaOffset, 4);
        writeTableRecord(out, "glyf", glyfOffset, 0);

        writeHeadTable(out);

        out.writeInt(0x00010000);
        out.writeShort(1);

        out.writeInt(0);
        out.flush();
        return output.toByteArray();
    }

    private static byte[] fontWithHeadOnly() throws IOException {
        int headOffset = 28;

        ByteArrayOutputStream output = new ByteArrayOutputStream();
        DataOutputStream out = new DataOutputStream(output);

        out.writeInt(0x00010000);
        out.writeShort(1);
        out.writeShort(0);
        out.writeShort(0);
        out.writeShort(0);
        writeTableRecord(out, "head", headOffset, 52);

        writeHeadTable(out);

        out.flush();
        return output.toByteArray();
    }

    private static void writeHeadTable(DataOutputStream out) throws IOException {
        out.writeInt(0);
        out.writeInt(0);
        out.writeInt(0);
        out.writeInt(0);
        out.writeShort(0);
        out.writeShort(1000);
        out.write(new byte[28]);
        out.writeShort(1);
        out.writeShort(0);
    }

    private static void writeTableRecord(
            DataOutputStream out, String tag, int offset, int length) throws IOException {
        out.writeBytes(tag);
        out.writeInt(0);
        out.writeInt(offset);
        out.writeInt(length);
    }
}

