        putU16(data, offset + 2, encoding);
        putU16(data, offset + 4, language);
        putU16(data, offset + 6, nameId);
        putU16(data, offset + 8, length);
        putU16(data, offset + 10, stringOffset);
    }

    private static void putUtf16(byte[] data, int offset, String value) {
        byte[] encoded = value.getBytes(StandardCharsets.UTF_16BE);
        System.arraycopy(encoded, 0, data, offset, encoded.length);
    }

    private static void putTag(byte[] data, int offset, String tag) {
        byte[] bytes = tag.getBytes(StandardCharsets.ISO_8859_1);
        System.arraycopy(bytes, 0, data, offset, 4);
    }

    private static void putU16(byte[] data, int offset, int value) {
        data[offset] = (byte) (value >>> 8);
        data[offset + 1] = (byte) value;
    }

    private static void putU32(byte[] data, int offset, long value) {
        data[offset] = (byte) (value >>> 24);
        data[offset + 1] = (byte) (value >>> 16);
        data[offset + 2] = (byte) (value >>> 8);
        data[offset + 3] = (byte) value;
    }
}

