    @Test
    void testRenderSkipsWhenNoBackgroundAndNoBorder() {
        CT_PageBlock layer = new CT_PageBlock();
        Div<Div> e = new Div<>(30d, 10d); // width 30, height 10
        // No background color, no border (default)
        AtomicInteger maxUnitID = new AtomicInteger(0);

