        assertEquals(0, maxUnitID.get(), "maxUnitID should remain unchanged when nothing is drawn.");
    }

    @Test
    void testRenderBackgroundAndEqualBordersProducesTwoBlocks() {
        CT_PageBlock layer = new CT_PageBlock();
        Div<Div> e = new Div<>(30d, 10d);
        e.setBackgroundColor(0, 0, 255); // blue background
        // Equal border widths on all sides
        e.setBorderTop(2d);
        e.setBorderRight(2d);
        e.setBorderBottom(2d);
        e.setBorderLeft(2d);

        AtomicInteger maxUnitID = new AtomicInteger(0);

        DivRender.render(layer, e, maxUnitID);

        // Background rectangle + one border block (since all borders are equal)
        assertEquals(2, layer.getPageBlocks().size(), "Expected two blocks: one background and one border when borders are equal.");
        assertEquals(2, maxUnitID.get(), "maxUnitID should have incremented by 2 for two drawn blocks.");
