    void testRenderUnbalancedBordersProducesFourBlocks() {
        CT_PageBlock layer = new CT_PageBlock();
        Div<Div> e = new Div<>(30d, 10d);
        // No background
        e.setBorderTop(1d);
        e.setBorderRight(2d);
        e.setBorderBottom(3d);
        e.setBorderLeft(4d);

        AtomicInteger maxUnitID = new AtomicInteger(0);

        DivRender.render(layer, e, maxUnitID);

        // Four borders drawn separately
        assertEquals(4, layer.getPageBlocks().size(), "Expected four blocks for unbalanced borders (top, right, bottom, left).");
        assertEquals(4, maxUnitID.get(), "maxUnitID should have incremented by 4 for four drawn borders.");
    }

    @Test
    void testRenderHeightNullThrowsIllegalArgument() {
        CT_PageBlock layer = new CT_PageBlock();
        Div<Div> e = new Div<>(); // height is not set
        AtomicInteger maxUnitID = new AtomicInteger(0);

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class, () -> DivRender.render(layer, e, maxUnitID));
        assertTrue(ex.getMessage().contains("高度"), "Exception message should indicate that height is required.");
    }

    @Test
    void testRenderBackgroundAndBordersProducesFiveBlocks() {
        CT_PageBlock layer = new CT_PageBlock();
        Div<Div> e = new Div<>(25d, 8d);
        e.setBackgroundColor(100, 100, 100); // gray background
        // Four borders with equal widths
        e.setBorderTop(1d);
        e.setBorderRight(1d);
        e.setBorderBottom(1d);
        e.setBorderLeft(1d);

        AtomicInteger maxUnitID = new AtomicInteger(0);

        DivRender.render(layer, e, maxUnitID);

        // 1 background + 4 borders = 5 blocks
        assertEquals(5, layer.getPageBlocks().size(), "Expected five blocks: background + four borders when borders are balanced with a background.");
        assertEquals(5, maxUnitID.get(), "maxUnitID should have incremented by 5 for five drawn blocks.");
    }
