                    "<OFD xmlns=\"http://www.ofdspec.org/2016\">" +
                    "<DocBody>" +
                    "<DocInfo/>" +
                    "<DocRoot>Doc_0/Document.xml</DocRoot>" +
                    "</DocBody>" +
                    "</OFD>");

            addEntry(zip, "Doc_0/Document.xml",
                    "<?xml version=\"1.0\" encoding=\"UTF-8\"?>" +
                    "<Document xmlns=\"http://www.ofdspec.org/2016\">" +
                    "<CommonData>" +
                    "<MaxUnitID>2</MaxUnitID>" +
                    "<PageArea><PhysicalBox>0 0 210 297</PhysicalBox></PageArea>" +
                    "<Pages>" +
                    "<Page ID=\"1\" BaseLoc=\"Pages/Page_0.xml\"/>" +
                    "<Page ID=\"2\" BaseLoc=\"Pages/Page_1.xml\"/>" +
                    "</Pages>" +
                    "</CommonData>" +
                    "<PublicRes/>" +
                    "<DocumentRes/>" +
                    "</Document>");

            addEntry(zip, "Doc_0/Pages/Page_0.xml",
                    "<?xml version=\"1.0\" encoding=\"UTF-8\"?>" +
                    "<Page xmlns=\"http://www.ofdspec.org/2016\" ID=\"1\">" +
                    "<Area><PhysicalBox>0 0 210 297</PhysicalBox></Area>" +
                    "</Page>");

            addEntry(zip, "Doc_0/Pages/Page_1.xml",
                    "<?xml version=\"1.0\" encoding=\"UTF-8\"?>" +
                    "<Page xmlns=\"http://www.ofdspec.org/2016\" ID=\"2\">" +
                    "<Area><PhysicalBox>0 0 210 297</PhysicalBox></Area>" +
                    "</Page>");
        }

        return new ByteArrayInputStream(output.toByteArray());
    }

    private static void addEntry(
            ZipOutputStream zip,
