    private static double yCoordinate(ST_Box box) {
        for (String methodName : new String[]{"getY", "getTop", "getTopY"}) {
            try {
                Method method = box.getClass().getMethod(methodName);
                Object value = method.invoke(box);
                if (value instanceof Number) {
                    return ((Number) value).doubleValue();
                }
            } catch (ReflectiveOperationException ignored) {
            }
        }

        Class<?> type = box.getClass();
        while (type != null) {
            try {
                Field field = type.getDeclaredField("y");
                field.setAccessible(true);
                return ((Number) field.get(box)).doubleValue();
            } catch (ReflectiveOperationException ignored) {
                type = type.getSuperclass();
            }
        }

        throw new AssertionError("Unable to read the Y coordinate from ST_Box");
    }
}

